// Force-Directed Tree — Network, route: ref
// Source: force-directed-tree
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from forceTree ----
type TreeNode = { name: string; children?: TreeNode[] };

/**
 * Class names keyed by their package path, in the style of the flare toolkit the
 * original notebook loads. A package may hold both leaves and sub-packages.
 */
const PACKAGES: Record<string, string[]> = {
  'analytics/cluster': ['AgglomerativeCluster', 'CommunityStructure', 'HierarchicalCluster', 'MergeEdge'],
  'analytics/graph': ['BetweennessCentrality', 'LinkDistance', 'MaxFlowMinCut', 'ShortestPaths', 'SpanningTree'],
  'analytics/optimization': ['AspectRatioBanker'],
  animate: [
    'Easing', 'FunctionSequence', 'Parallel', 'Pause', 'Scheduler',
    'Sequence', 'Transition', 'Transitioner', 'Tween'
  ],
  'animate/interpolate': [
    'ArrayInterpolator', 'ColorInterpolator', 'DateInterpolator', 'Interpolator', 'MatrixInterpolator',
    'NumberInterpolator', 'ObjectInterpolator', 'PointInterpolator', 'RectangleInterpolator'
  ],
  data: ['Data', 'DataField', 'DataSchema', 'DataSet', 'DataSource', 'DataTable', 'DataUtil'],
  'data/converters': [
    'Converters', 'DelimitedTextConverter', 'GraphMLConverter', 'IDataConverter', 'JSONConverter'
  ],
  physics: [
    'DragForce', 'GravityForce', 'IForce', 'NBodyForce', 'Particle', 'Simulation', 'Spring', 'SpringForce'
  ],
  query: [
    'Add', 'And', 'Arithmetic', 'Average', 'BinaryExpression', 'Comparison', 'CompositeExpression',
    'Count', 'DateUtil', 'Distinct', 'Expression', 'ExpressionIterator', 'Fn', 'If', 'IsA',
    'Literal', 'Match', 'Maximum', 'Minimum', 'Not', 'Or', 'Query', 'Range', 'StringUtil',
    'Sum', 'Variable', 'Variance', 'Xor'
  ],
  'query/methods': [
    'add', 'average', 'count', 'distinct', 'div', 'eq', 'gt', 'lt', 'max', 'min',
    'mul', 'neq', 'orderby', 'range', 'select', 'sub', 'sum', 'update', 'where'
  ],
  scale: [
    'IScaleMap', 'LinearScale', 'LogScale', 'OrdinalScale', 'QuantileScale',
    'QuantitativeScale', 'RootScale', 'Scale', 'ScaleType', 'TimeScale'
  ],
  util: [
    'Arrays', 'Colors', 'Dates', 'Displays', 'Filter', 'Geometry', 'Maths',
    'Orientation', 'Property', 'Shapes', 'Sort', 'Stats', 'Strings'
  ],
  'util/heap': ['FibonacciHeap', 'HeapNode'],
  'util/math': ['DenseMatrix', 'IMatrix', 'SparseMatrix'],
  'util/palette': ['ColorPalette', 'Palette', 'ShapePalette', 'SizePalette'],
  vis: ['Visualization'],
  'vis/axis': ['Axes', 'Axis', 'AxisGridLine', 'AxisLabel', 'CartesianAxes'],
  'vis/controls': [
    'AnchorControl', 'ClickControl', 'Control', 'DragControl', 'ExpandControl',
    'HoverControl', 'PanZoomControl', 'SelectionControl', 'TooltipControl'
  ],
  'vis/data': ['DataList', 'DataSprite', 'EdgeSprite', 'NodeSprite', 'ScaleBinding', 'Tree', 'TreeBuilder'],
  'vis/events': ['DataEvent', 'SelectionEvent', 'TooltipEvent', 'VisualizationEvent'],
  'vis/legend': ['Legend', 'LegendItem', 'LegendRange'],
  'vis/operator': ['Operator', 'OperatorList', 'OperatorSequence', 'OperatorSwitch', 'SortOperator'],
  'vis/layout': [
    'AxisLayout', 'BundledEdgeRouter', 'CircleLayout', 'DendrogramLayout', 'ForceDirectedLayout',
    'IcicleTreeLayout', 'IndentedTreeLayout', 'Layout', 'NodeLinkTreeLayout', 'PieLayout',
    'RadialTreeLayout', 'StackedAreaLayout', 'TreeMapLayout'
  ]
};

function buildTree(): TreeNode {
  const root: TreeNode = { name: 'flare', children: [] };

  for (const [path, leaves] of Object.entries(PACKAGES)) {
    let parent = root;
    for (const segment of path.split('/')) {
      const children = parent.children ?? (parent.children = []);
      let next = children.find((child) => child.name === segment);
      if (!next) {
        next = { name: segment, children: [] };
        children.push(next);
      }
      parent = next;
    }
    parent.children?.push(...leaves.map((name) => ({ name })));
  }

  return root;
}

/** Top-level package names, in declaration order, for the color scale. */
const PACKAGE_NAMES: string[] = Array.from(
  new Set(Object.keys(PACKAGES).map((path) => path.split('/')[0]))
);

const flareTree: TreeNode = buildTree();

type SimNode = d3.HierarchyNode<TreeNode> & d3.SimulationNodeDatum;
type SimLink = d3.SimulationLinkDatum<SimNode>;

/** Reserved band at the top for the package legend; the tree is fitted below it. */
const LEGEND_HEIGHT = 24;
const SETTLE_TICKS = 400;
const SEED = 20260813;
const PADDING = 12;

/** A hierarchy whose own parent-child edges become the links, plus its top-level group names. */
export type Data = { tree: TreeNode; packages: string[] };

const DEMO: Data = { tree: flareTree, packages: PACKAGE_NAMES };

// forceLink may replace an endpoint with an id, so read positions defensively.
const at = (end: SimLink['source'], axis: 'x' | 'y') => (end as SimNode)[axis] ?? 0;

export default function ForceDirectedTree({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const svgRef = useRef<SVGSVGElement>(null);
  const height = Math.round(width * 0.66);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>(data.packages, d3.schemeObservable10),
    [data]
  );

  // The hierarchy nodes are the simulation nodes, exactly as in the notebook: links come
  // from root.links() rather than a separate edge list.
  const { nodes, links, seeds, packageOf } = useMemo(() => {
    const root = d3.hierarchy(data.tree);
    const nodes = root.descendants() as SimNode[];
    const links = root.links() as SimLink[];

    const packageOf = new Map<SimNode, string>();
    for (const node of nodes) {
      const chain = node.ancestors();
      const top = chain[chain.length - 2];
      if (top) packageOf.set(node, top.data.name);
    }

    // Pre-order index gives siblings adjacent angles, so the force only has to untangle
    // depth. Seeded jitter breaks the ties d3-force would otherwise resolve randomly.
    const random = d3.randomLcg(SEED);
    const seeds = nodes.map((node, i) => ({
      x: Math.cos((i / nodes.length) * 2 * Math.PI) * (20 + node.depth * 45) + (random() - 0.5) * 8,
      y: Math.sin((i / nodes.length) * 2 * Math.PI) * (20 + node.depth * 45) + (random() - 0.5) * 8
    }));

    return { nodes, links, seeds, packageOf };
  }, [data]);

  useEffect(() => {
    if (!svgRef.current || width === 0) return;
    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice in development.

    // Reset every node: the simulation mutates the shared hierarchy, so a remount must
    // start from the seeds rather than from the settled positions of the previous run.
    nodes.forEach((node, i) => {
      node.x = seeds[i].x;
      node.y = seeds[i].y;
      node.vx = 0;
      node.vy = 0;
      node.fx = null;
      node.fy = null;
    });

    const simulation = d3
      .forceSimulation<SimNode>(nodes)
      .randomSource(d3.randomLcg(SEED))
      .force('link', d3.forceLink<SimNode, SimLink>(links).distance(0).strength(1))
      .force('charge', d3.forceManyBody<SimNode>().strength(-50))
      .force('x', d3.forceX<SimNode>())
      .force('y', d3.forceY<SimNode>())
      .stop();
    simulation.tick(SETTLE_TICKS);

    const [x0, x1] = d3.extent(nodes, (d) => d.x ?? 0);
    const [y0, y1] = d3.extent(nodes, (d) => d.y ?? 0);
    const spanX = Math.max((x1 ?? 0) - (x0 ?? 0), 1);
    const spanY = Math.max((y1 ?? 0) - (y0 ?? 0), 1);
    const k = Math.min(
      (width - PADDING * 2) / spanX,
      (height - LEGEND_HEIGHT - PADDING * 2) / spanY
    );
    const tx = width / 2 - (k * ((x0 ?? 0) + (x1 ?? 0))) / 2;
    const ty = LEGEND_HEIGHT + (height - LEGEND_HEIGHT) / 2 - (k * ((y0 ?? 0) + (y1 ?? 0))) / 2;

    const slot = width / data.packages.length;
    if (slot >= 62) {
      svg
        .append('g')
        .attr('font-size', 11)
        .attr('fill', 'var(--muted)')
        .selectAll('g')
        .data(data.packages)
        .join('g')
        .attr('transform', (_, i) => `translate(${8 + i * slot},15)`)
        .call((g) => g.append('circle').attr('r', 4).attr('fill', (d) => color(d)))
        .call((g) =>
          g
            .append('text')
            .attr('x', 10)
            .attr('dy', '0.32em')
            .text((d) => d)
        );
    }

    // One fitted container so the settled layout fills the frame at any gallery width;
    // mark sizes divide by k to stay constant on screen.
    const container = svg.append('g').attr('transform', `translate(${tx},${ty}) scale(${k})`);

    const link = container
      .append('g')
      .attr('stroke', 'var(--muted)')
      .attr('stroke-opacity', 0.5)
      .attr('stroke-width', 1 / k)
      .selectAll('line')
      .data(links)
      .join('line')
      .attr('x1', (d) => at(d.source, 'x'))
      .attr('y1', (d) => at(d.source, 'y'))
      .attr('x2', (d) => at(d.target, 'x'))
      .attr('y2', (d) => at(d.target, 'y'));

    const hue = (d: SimNode) => {
      const name = packageOf.get(d);
      return name ? color(name) : 'var(--text)';
    };

    const node = container
      .append('g')
      .attr('stroke-width', 1.5 / k)
      .selectAll<SVGCircleElement, SimNode>('circle')
      .data(nodes)
      .join('circle')
      .attr('r', (d) => (d.children ? 3.5 : 3) / k)
      .attr('fill', (d) => (d.children ? 'var(--bg)' : hue(d)))
      .attr('stroke', (d) => (d.children ? hue(d) : 'var(--bg)'))
      .attr('cx', (d) => d.x ?? 0)
      .attr('cy', (d) => d.y ?? 0)
      .style('cursor', 'grab');

    node.append('title').text((d) => d.data.name);

    const ticked = () => {
      link
        .attr('x1', (d) => at(d.source, 'x'))
        .attr('y1', (d) => at(d.source, 'y'))
        .attr('x2', (d) => at(d.target, 'x'))
        .attr('y2', (d) => at(d.target, 'y'));
      node.attr('cx', (d) => d.x ?? 0).attr('cy', (d) => d.y ?? 0);
    };
    simulation.on('tick', ticked);

    const drag = d3
      .drag<SVGCircleElement, SimNode>()
      .on('start', (event, d) => {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
      })
      .on('drag', (event, d) => {
        d.fx = event.x;
        d.fy = event.y;
      })
      .on('end', (event, d) => {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
      });
    node.call(drag);

    return () => {
      simulation.on('tick', null).stop();
      node.on('.drag', null);
      svg.selectAll('*').remove();
    };
  }, [data, width, height, nodes, links, seeds, packageOf, color]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Force-directed layout of a software package hierarchy, with links taken from the tree itself and draggable nodes"
    />
  );
}
